import{_ as e,o as i,c as r,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"架构与进程模型","description":"","frontmatter":{"title":"架构与进程模型","outline":[2,3],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"frontend/guide/core/web/browser/architecture.md","filePath":"frontend/guide/core/web/browser/architecture.md","lastUpdated":1785217527000}'),l={name:"frontend/guide/core/web/browser/architecture.md"};function s(n,a,o,h,d,p){return i(),r("div",null,[...a[0]||(a[0]=[t(`<h1 id="架构与进程模型" tabindex="-1">架构与进程模型 <a class="header-anchor" href="#架构与进程模型" aria-label="Permalink to &quot;架构与进程模型&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>现代浏览器同时是网络客户端、文档运行时、图形合成器、权限代理和多进程桌面应用。页面脚本看到的是 Window、Document 和 Web API；浏览器内部则通过进程隔离、线程调度与 IPC 把导航、渲染、网络、存储和设备访问连接起来。</p><p>本篇以 Chromium 的可公开验证模型说明通用原则。Firefox、Safari 的组件名称和进程分配不同，不能把“一个标签页等于一个渲染进程”等常见简化写成跨浏览器保证。</p><h2 id="_1-为什么使用多进程" tabindex="-1">1. 为什么使用多进程 <a class="header-anchor" href="#_1-为什么使用多进程" aria-label="Permalink to &quot;1. 为什么使用多进程&quot;">​</a></h2><h3 id="_1-1-稳定性隔离" tabindex="-1">1.1 稳定性隔离 <a class="header-anchor" href="#_1-1-稳定性隔离" aria-label="Permalink to &quot;1.1 稳定性隔离&quot;">​</a></h3><p>单个页面的渲染进程崩溃时，浏览器 UI 和其他页面仍有机会继续运行。独立进程也让操作系统能够分别调度、限制和回收后台页面资源。</p><p>隔离不是绝对的：多个文档可能共享进程，GPU 或网络等服务也会被多个标签页共同使用，因此某些故障仍可能影响多个页面。</p><h3 id="_1-2-安全边界" tabindex="-1">1.2 安全边界 <a class="header-anchor" href="#_1-2-安全边界" aria-label="Permalink to &quot;1.2 安全边界&quot;">​</a></h3><p>网页内容来自不可信网络。浏览器把渲染器放入沙箱，限制其直接访问文件系统、设备和其他站点数据；需要权限的操作通过浏览器进程或专用服务代理。</p><p>即使渲染引擎出现漏洞，攻击者还需要突破沙箱或其他隔离层才能获得更高系统权限。前端安全策略仍然必要，多进程不能修复 XSS、CSRF 或错误授权。</p><h3 id="_1-3-性能与响应" tabindex="-1">1.3 性能与响应 <a class="header-anchor" href="#_1-3-性能与响应" aria-label="Permalink to &quot;1.3 性能与响应&quot;">​</a></h3><p>浏览器 UI、网络、合成和页面 JavaScript 分开调度，可以减少一个繁忙页面完全冻结整个浏览器的概率。代价是：</p><ul><li>每个进程都有内存基础开销；</li><li>跨进程操作需要消息序列化和同步；</li><li>页面、frame 与进程的关系更复杂；</li><li>多个进程仍会争用 CPU、GPU、内存和磁盘。</li></ul><h2 id="_2-主要进程" tabindex="-1">2. 主要进程 <a class="header-anchor" href="#_2-主要进程" aria-label="Permalink to &quot;2. 主要进程&quot;">​</a></h2><h3 id="_2-1-浏览器进程" tabindex="-1">2.1 浏览器进程 <a class="header-anchor" href="#_2-1-浏览器进程" aria-label="Permalink to &quot;2.1 浏览器进程&quot;">​</a></h3><p>浏览器进程管理窗口与标签页、导航决策、权限提示、会话历史和其他进程生命周期。它持有高权限，不执行普通页面 DOM 和大多数页面 JavaScript。</p><p>在 Chromium 中，页面请求文件选择、定位或剪贴板等敏感能力时，渲染器不能直接绕过浏览器进程访问系统资源。</p><h3 id="_2-2-渲染进程" tabindex="-1">2.2 渲染进程 <a class="header-anchor" href="#_2-2-渲染进程" aria-label="Permalink to &quot;2.2 渲染进程&quot;">​</a></h3><p>渲染器负责一个或多个 Document 的主要 Web 平台工作：</p><ul><li>HTML 与 CSS 解析；</li><li>DOM、CSSOM 和布局；</li><li>JavaScript 执行；</li><li>事件分发；</li><li>绘制记录和部分合成准备。</li></ul><p>渲染器运行在沙箱中。一个标签页可能包含多个跨站 frame，并由多个渲染进程共同呈现；同一渲染进程也可能承载多个符合复用策略的文档。</p><h3 id="_2-3-gpu-进程" tabindex="-1">2.3 GPU 进程 <a class="header-anchor" href="#_2-3-gpu-进程" aria-label="Permalink to &quot;2.3 GPU 进程&quot;">​</a></h3><p>GPU 进程接收合成与光栅相关工作，协调图形 API 和驱动。独立进程可隔离不稳定驱动，并让多个渲染器共享 GPU 资源。</p><p>不是所有 CSS 变化都会“交给 GPU 就免费完成”。样式、布局、绘制和纹理上传仍可能在主线程或其他线程产生明显成本。</p><h3 id="_2-4-网络服务" tabindex="-1">2.4 网络服务 <a class="header-anchor" href="#_2-4-网络服务" aria-label="Permalink to &quot;2.4 网络服务&quot;">​</a></h3><p>网络服务负责连接、代理、DNS、TLS、HTTP、缓存和请求调度等能力。浏览器实现会演进，不能依赖某个请求固定运行在哪个线程；Web 应用应依据 Fetch 与网络协议的公开行为编程。</p><h3 id="_2-5-存储与-utility-进程" tabindex="-1">2.5 存储与 Utility 进程 <a class="header-anchor" href="#_2-5-存储与-utility-进程" aria-label="Permalink to &quot;2.5 存储与 Utility 进程&quot;">​</a></h3><p>浏览器可能把存储、音视频解码、PDF、扩展或其他高风险任务放入专用或 Utility 进程。拆分方式是实现细节，开发者更应关注 origin、配额、权限和 API 生命周期。</p><h2 id="_3-页面、frame、site-与进程" tabindex="-1">3. 页面、Frame、Site 与进程 <a class="header-anchor" href="#_3-页面、frame、site-与进程" aria-label="Permalink to &quot;3. 页面、Frame、Site 与进程&quot;">​</a></h2><h3 id="_3-1-标签页不是进程单位" tabindex="-1">3.1 标签页不是进程单位 <a class="header-anchor" href="#_3-1-标签页不是进程单位" aria-label="Permalink to &quot;3.1 标签页不是进程单位&quot;">​</a></h3><p>以下说法都不可靠：</p><ul><li>一个标签页永远只有一个渲染进程；</li><li>一个 iframe 永远与父页面同进程；</li><li>两个标签页永远使用不同进程；</li><li>Worker 永远拥有独立操作系统进程。</li></ul><p>进程分配受站点隔离、内存压力、浏览器策略和平台影响。</p><h3 id="_3-2-frame-与-document" tabindex="-1">3.2 Frame 与 Document <a class="header-anchor" href="#_3-2-frame-与-document" aria-label="Permalink to &quot;3.2 Frame 与 Document&quot;">​</a></h3><p>页面的顶层文档和 iframe 各自对应 frame。导航后，同一个 frame 会承载新的 Document；旧 Document 可能销毁，也可能进入往返缓存。</p><p>WindowProxy 让 JavaScript 在导航前后仍能持有对窗口位置的引用，但跨源访问会受到同源策略限制。</p><h3 id="_3-3-origin-与-site" tabindex="-1">3.3 Origin 与 Site <a class="header-anchor" href="#_3-3-origin-与-site" aria-label="Permalink to &quot;3.3 Origin 与 Site&quot;">​</a></h3><p>Origin 通常由 scheme、host 和 port 组成，是 DOM、存储和许多权限的安全边界。Site 的定义更宽，浏览器可把同站点文档作为进程隔离单位。</p><p>不能因为两个页面可能同进程就认为它们可以互相读 DOM；也不能因为分属不同进程就认为 postMessage 不可用。安全语义由 Web 标准决定，进程只是实现手段。</p><h3 id="_3-4-site-isolation-与-oopif" tabindex="-1">3.4 Site Isolation 与 OOPIF <a class="header-anchor" href="#_3-4-site-isolation-与-oopif" aria-label="Permalink to &quot;3.4 Site Isolation 与 OOPIF&quot;">​</a></h3><p>站点隔离可以让跨站 iframe 进入不同渲染进程，降低被攻陷渲染器读取其他站点敏感数据的风险。浏览器进程维护 frame 树和代理，跨进程输入、焦点、导航与合成通过 IPC 协调。</p><p>对前端最直接的影响是：跨 frame 调用应遵循异步消息模型，不依赖内部是否同进程；大量跨 frame 消息也会有序列化和调度成本。</p><h2 id="_4-渲染器中的线程" tabindex="-1">4. 渲染器中的线程 <a class="header-anchor" href="#_4-渲染器中的线程" aria-label="Permalink to &quot;4. 渲染器中的线程&quot;">​</a></h2><h3 id="_4-1-主线程" tabindex="-1">4.1 主线程 <a class="header-anchor" href="#_4-1-主线程" aria-label="Permalink to &quot;4.1 主线程&quot;">​</a></h3><p>页面主线程通常承担：</p><ul><li>执行大多数 JavaScript；</li><li>DOM 和样式计算；</li><li>布局；</li><li>生成绘制记录；</li><li>事件回调和微任务；</li><li>部分解析工作。</li></ul><p>长任务会同时推迟输入处理、计时器和渲染机会，因此“JavaScript 计算只影响脚本，不影响页面”是错误认识。</p><h3 id="_4-2-合成线程" tabindex="-1">4.2 合成线程 <a class="header-anchor" href="#_4-2-合成线程" aria-label="Permalink to &quot;4.2 合成线程&quot;">​</a></h3><p>合成线程维护图层、滚动和最终合成提交。满足条件的滚动与 transform / opacity 动画可以减少主线程参与，但命中测试、事件监听和页面结构仍可能让主线程成为瓶颈。</p><h3 id="_4-3-光栅线程" tabindex="-1">4.3 光栅线程 <a class="header-anchor" href="#_4-3-光栅线程" aria-label="Permalink to &quot;4.3 光栅线程&quot;">​</a></h3><p>绘制指令需要转成像素瓦片，浏览器可使用多个光栅线程并在合适时利用 GPU。大面积绘制、阴影、滤镜和高分辨率内容仍可能消耗明显时间与显存。</p><h3 id="_4-4-worker-线程" tabindex="-1">4.4 Worker 线程 <a class="header-anchor" href="#_4-4-worker-线程" aria-label="Permalink to &quot;4.4 Worker 线程&quot;">​</a></h3><p>Dedicated Worker 等通常在渲染器相关进程的工作线程运行，拥有独立事件循环和全局环境。它们不访问 DOM，通过 structured clone 或 transferable 与页面通信。</p><p>Worker 是否对应独立操作系统进程不是 API 契约，见<a href="/frontend/guide/core/web/apis/workers">Worker 与跨上下文通信</a>。</p><h2 id="_5-导航的数据流" tabindex="-1">5. 导航的数据流 <a class="header-anchor" href="#_5-导航的数据流" aria-label="Permalink to &quot;5. 导航的数据流&quot;">​</a></h2><h3 id="_5-1-导航开始" tabindex="-1">5.1 导航开始 <a class="header-anchor" href="#_5-1-导航开始" aria-label="Permalink to &quot;5.1 导航开始&quot;">​</a></h3><p>用户点击链接、输入地址、调用 Location 或提交表单都可能启动导航。浏览器进程判断导航目标、下载策略、权限、安全检查和是否需要更换渲染进程。</p><h3 id="_5-2-网络响应" tabindex="-1">5.2 网络响应 <a class="header-anchor" href="#_5-2-网络响应" aria-label="Permalink to &quot;5.2 网络响应&quot;">​</a></h3><p>网络服务建立连接并取得响应头与内容。重定向、Content-Type、下载处理、CSP 和站点隔离都可能改变后续路径。</p><h3 id="_5-3-提交文档" tabindex="-1">5.3 提交文档 <a class="header-anchor" href="#_5-3-提交文档" aria-label="Permalink to &quot;5.3 提交文档&quot;">​</a></h3><p>浏览器为目标 frame 选择或创建渲染器，把响应交给解析器并提交新的 Document。旧页面可能触发 pagehide，也可能因 bfcache 被保留。</p><h3 id="_5-4-渲染与呈现" tabindex="-1">5.4 渲染与呈现 <a class="header-anchor" href="#_5-4-渲染与呈现" aria-label="Permalink to &quot;5.4 渲染与呈现&quot;">​</a></h3><p>渲染器解析文档、执行脚本、计算样式与布局、生成绘制信息；光栅和合成系统把结果提交到屏幕。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户导航</span></span>
<span class="line"><span>  -&gt; 浏览器进程决策</span></span>
<span class="line"><span>  -&gt; 网络服务请求与响应</span></span>
<span class="line"><span>  -&gt; 选择渲染进程</span></span>
<span class="line"><span>  -&gt; 创建 Document</span></span>
<span class="line"><span>  -&gt; 解析、脚本、样式与布局</span></span>
<span class="line"><span>  -&gt; 绘制、光栅与合成</span></span>
<span class="line"><span>  -&gt; 屏幕呈现</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这些阶段会重叠。预加载扫描、流式解析和增量渲染意味着浏览器不必等整个 HTML 下载完成才开始后续工作。</p><h2 id="_6-ipc-与异步边界" tabindex="-1">6. IPC 与异步边界 <a class="header-anchor" href="#_6-ipc-与异步边界" aria-label="Permalink to &quot;6. IPC 与异步边界&quot;">​</a></h2><h3 id="_6-1-为什么需要-ipc" tabindex="-1">6.1 为什么需要 IPC <a class="header-anchor" href="#_6-1-为什么需要-ipc" aria-label="Permalink to &quot;6.1 为什么需要 IPC&quot;">​</a></h3><p>高权限浏览器进程、沙箱渲染器、GPU 和服务进程不能直接共享任意内存对象。它们通过 IPC 发送结构化消息、资源句柄和状态变更。</p><h3 id="_6-2-同步调用的代价" tabindex="-1">6.2 同步调用的代价 <a class="header-anchor" href="#_6-2-同步调用的代价" aria-label="Permalink to &quot;6.2 同步调用的代价&quot;">​</a></h3><p>跨进程同步等待会增加延迟和死锁风险，因此浏览器内部与 Web API 都尽量使用异步模型。文件选择、权限请求、剪贴板和网络 API 返回 Promise 或回调不是偶然风格。</p><h3 id="_6-3-页面可观察的边界" tabindex="-1">6.3 页面可观察的边界 <a class="header-anchor" href="#_6-3-页面可观察的边界" aria-label="Permalink to &quot;6.3 页面可观察的边界&quot;">​</a></h3><ul><li>iframe 通过 postMessage 通信；</li><li>Worker 通过 MessagePort 或 postMessage 通信；</li><li>Service Worker 与页面异步交换消息；</li><li>GPU 合成完成不等于 JavaScript 同步得到像素；</li><li>导航调用没有同步“加载完成”返回值。</li></ul><p>前端应围绕事件、Promise、AbortSignal 和版本化消息协议设计。</p><h2 id="_7-隔离、崩溃与资源回收" tabindex="-1">7. 隔离、崩溃与资源回收 <a class="header-anchor" href="#_7-隔离、崩溃与资源回收" aria-label="Permalink to &quot;7. 隔离、崩溃与资源回收&quot;">​</a></h2><h3 id="_7-1-renderer-sandbox" tabindex="-1">7.1 Renderer sandbox <a class="header-anchor" href="#_7-1-renderer-sandbox" aria-label="Permalink to &quot;7.1 Renderer sandbox&quot;">​</a></h3><p>渲染器访问网络、文件、设备和凭证时受到代理与策略限制。沙箱减小浏览器漏洞影响，但页面脚本仍能读取同源可访问数据，所以 XSS 仍然危险。</p><h3 id="_7-2-崩溃影响" tabindex="-1">7.2 崩溃影响 <a class="header-anchor" href="#_7-2-崩溃影响" aria-label="Permalink to &quot;7.2 崩溃影响&quot;">​</a></h3><p>同一渲染进程承载的多个 frame 或页面可能一起崩溃。浏览器也可能因为 GPU、网络或扩展故障影响多个标签页。</p><h3 id="_7-3-后台页面" tabindex="-1">7.3 后台页面 <a class="header-anchor" href="#_7-3-后台页面" aria-label="Permalink to &quot;7.3 后台页面&quot;">​</a></h3><p>后台标签页可能被降低优先级、限制计时器、冻结甚至丢弃。页面恢复时要重新验证时间、网络和数据，不应假设内存状态持续运行。</p><h3 id="_7-4-内存压力" tabindex="-1">7.4 内存压力 <a class="header-anchor" href="#_7-4-内存压力" aria-label="Permalink to &quot;7.4 内存压力&quot;">​</a></h3><p>多进程提升隔离，也带来更多内存开销。大量 iframe、Worker、图层和缓存会共同消耗资源；“拆到 Worker”不是免费的性能优化。</p><h2 id="_8-不同浏览器的差异" tabindex="-1">8. 不同浏览器的差异 <a class="header-anchor" href="#_8-不同浏览器的差异" aria-label="Permalink to &quot;8. 不同浏览器的差异&quot;">​</a></h2><h3 id="_8-1-只依赖标准行为" tabindex="-1">8.1 只依赖标准行为 <a class="header-anchor" href="#_8-1-只依赖标准行为" aria-label="Permalink to &quot;8.1 只依赖标准行为&quot;">​</a></h3><p>Browser、Renderer、Blink、V8、GPU Process 是 Chromium 语境。Safari 使用 WebKit，Firefox 使用 Gecko，各自的进程和线程划分不同。</p><p>业务代码依赖 DOM、Fetch、HTML 和 ECMAScript 标准，不依赖内部组件名称。</p><h3 id="_8-2-可以依赖的事实" tabindex="-1">8.2 可以依赖的事实 <a class="header-anchor" href="#_8-2-可以依赖的事实" aria-label="Permalink to &quot;8.2 可以依赖的事实&quot;">​</a></h3><ul><li>JavaScript 回调遵循事件循环和 run-to-completion；</li><li>同源策略限制跨源读取；</li><li>DOM 与 CSS 会形成可观察渲染结果；</li><li>页面可通过标准事件和 API 感知生命周期；</li><li>长主线程任务会推迟交互与渲染。</li></ul><h3 id="_8-3-不能当成保证的实现" tabindex="-1">8.3 不能当成保证的实现 <a class="header-anchor" href="#_8-3-不能当成保证的实现" aria-label="Permalink to &quot;8.3 不能当成保证的实现&quot;">​</a></h3><ul><li>tab 与 process 一一对应；</li><li>transform 动画永远不占主线程；</li><li>HTTP 请求一定来自某个固定进程；</li><li>hidden 页面永不运行；</li><li>DevTools 显示的内部线程名跨版本稳定。</li></ul><h2 id="_9-验证案例-跨站-iframe" tabindex="-1">9. 验证案例：跨站 iframe <a class="header-anchor" href="#_9-验证案例-跨站-iframe" aria-label="Permalink to &quot;9. 验证案例：跨站 iframe&quot;">​</a></h2><p>准备一个包含同源和跨站 iframe 的页面：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/same-origin.html&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.org/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>按以下路径验证：</p><ol><li>打开浏览器任务管理器，记录页面相关进程和内存。</li><li>在 DevTools Performance 录制中查看 Main、Compositor、Raster 等轨道。</li><li>在 Elements 面板确认两个 iframe 都属于同一逻辑 frame 树。</li><li>在 Console 尝试读取同源 frame DOM，应按加载状态和同源规则成功。</li><li>尝试读取跨源 frame DOM，应被同源策略阻止。</li><li>使用 <code>postMessage()</code> 与跨源 frame 建立允许的异步通信。</li><li>关闭或导航 frame，再观察进程和内存变化。</li></ol><p>预期结论不是“必定看到三个进程”，而是：</p><table tabindex="0"><thead><tr><th>观察</th><th>可得结论</th></tr></thead><tbody><tr><td>跨站 frame 可能出现在独立 renderer</td><td>站点隔离影响进程分配</td></tr><tr><td>Elements 仍呈现一棵 frame 关系</td><td>逻辑文档树不等于进程树</td></tr><tr><td>跨源 DOM 访问被阻止</td><td>安全边界由 origin 决定</td></tr><tr><td>postMessage 可以通信</td><td>跨源允许受控异步消息</td></tr><tr><td>不同机器进程数量不同</td><td>分配是浏览器实现与策略</td></tr></tbody></table><h2 id="_10-常见误区" tabindex="-1">10. 常见误区 <a class="header-anchor" href="#_10-常见误区" aria-label="Permalink to &quot;10. 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确理解</th></tr></thead><tbody><tr><td>一个标签页就是一个进程</td><td>frame、site 和策略共同决定</td></tr><tr><td>Renderer 等于浏览器</td><td>Renderer 只承担页面内容的一部分</td></tr><tr><td>多进程让页面自动并行</td><td>单个 Document 的主线程仍可能阻塞</td></tr><tr><td>GPU 动画没有成本</td><td>合成、纹理和内存仍有代价</td></tr><tr><td>沙箱消除了 XSS</td><td>XSS 仍可访问页面本来有权访问的数据</td></tr><tr><td>Worker 一定是独立进程</td><td>API 只保证独立执行环境</td></tr><tr><td>页面后台只是不显示</td><td>计时器、优先级和生命周期都可能改变</td></tr><tr><td>Chromium 内部名称是 Web 标准</td><td>只能作为实现案例</td></tr></tbody></table><h2 id="_11-参考资料" tabindex="-1">11. 参考资料 <a class="header-anchor" href="#_11-参考资料" aria-label="Permalink to &quot;11. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.chromium.org/developers/design-documents/multi-process-architecture/" target="_blank" rel="noreferrer">Chromium：Multi-process Architecture</a></li><li><a href="https://www.chromium.org/developers/design-documents/site-isolation/" target="_blank" rel="noreferrer">Chromium：Site Isolation</a></li><li><a href="https://www.chromium.org/developers/design-documents/oop-iframes/" target="_blank" rel="noreferrer">Chromium：Out-of-Process iframes</a></li><li><a href="https://www.chromium.org/developers/design-documents/inter-process-communication/" target="_blank" rel="noreferrer">Chromium：Inter-process Communication</a></li><li><a href="https://html.spec.whatwg.org/multipage/webappapis.html" target="_blank" rel="noreferrer">HTML Standard：Web application APIs</a></li></ul>`,102)])])}const m=e(l,[["render",s]]);export{u as __pageData,m as default};
